<script setup lang="ts">
import {ref,watch,onBeforeUnmount,nextTick,computed} from 'vue'
import {useI18n} from 'vue-i18n'
import type {Candidate,Task,EarthLimit,SeriesResponse,FeatureScore} from '../types'
import {api,errorMessage} from '../api'
import {localized} from '../i18n'
import Chart from './Chart.vue'
const props=defineProps<{candidate:Candidate;tasks:Task[];limits:EarthLimit[];siteId:string;mission:string}>()
const emit=defineEmits<{close:[]}>();const {t,locale}=useI18n()
const dialog=ref<HTMLDialogElement>();const series=ref<SeriesResponse>();const selectedFeature=ref('');const error=ref('');const loading=ref(false)
let requestId=0;let previous:HTMLElement|null=null
const format=(v:FeatureScore['target_value'])=>v===null?'—':Array.isArray(v)?`[${v.length} bands]`:typeof v==='number'?Number(v.toFixed(3)):v
const seriesFeatures=computed(()=>Object.values(props.candidate.tasks).flatMap(task=>task.features).filter(f=>f.feature.type==='timeseries'))
async function loadSeries(id:string){const request=++requestId;selectedFeature.value=id;loading.value=true;error.value='';series.value=undefined;try{const result=await api.series(props.candidate.id,id,props.siteId,props.mission);if(request===requestId)series.value=result}catch(e){if(request===requestId)error.value=errorMessage(e)}finally{if(request===requestId)loading.value=false}}
watch(()=>props.candidate.id,async()=>{requestId++;series.value=undefined;error.value='';selectedFeature.value='';if(!dialog.value?.open){previous=document.activeElement as HTMLElement;await nextTick();dialog.value?.showModal()}if(seriesFeatures.value[0])loadSeries(seriesFeatures.value[0].feature.id)},{immediate:true})
function close(){dialog.value?.close();emit('close');previous?.focus()}
onBeforeUnmount(()=>{requestId++;dialog.value?.close();previous?.focus()})
const chartBase={backgroundColor:'transparent',textStyle:{color:'#b3c0ce'},grid:{left:55,right:25,bottom:45,top:38},tooltip:{trigger:'axis' as const},legend:{textStyle:{color:'#b3c0ce'}},yAxis:{type:'value' as const,splitLine:{lineStyle:{color:'#26313d'}}}}
const phaseOption=computed(()=>({...chartBase,xAxis:{type:'value' as const,name:t('phase'),max:1},series:[{name:t('target'),type:'line' as const,showSymbol:false,data:series.value?.phase.map((x,i)=>[x,series.value!.target[i]]),color:'#94c9f0'},{name:t('candidate'),type:'line' as const,showSymbol:false,data:series.value?.phase.map((x,i)=>[x,series.value!.candidate[i]]),color:'#94ddbc'}]}))
const ecdfOption=computed(()=>({...chartBase,xAxis:{type:'value' as const},yAxis:{...chartBase.yAxis,min:0,max:1},series:[{name:t('target'),type:'line' as const,step:'end' as const,showSymbol:false,data:series.value?.target_ecdf.x.map((x,i)=>[x,series.value!.target_ecdf.y[i]]),color:'#94c9f0'},{name:t('candidate'),type:'line' as const,step:'end' as const,showSymbol:false,data:series.value?.candidate_ecdf.x.map((x,i)=>[x,series.value!.candidate_ecdf.y[i]]),color:'#94ddbc'}]}))
</script>
<template><dialog ref="dialog" class="detail-drawer" aria-labelledby="site-detail-title" @cancel.prevent="close" @click="e=>{if(e.target===dialog)close()}"><div class="drawer-inner"><div class="drawer-heading"><div><span class="eyebrow">SITE / {{candidate.id.toUpperCase()}}</span><h2 id="site-detail-title">{{candidate.name}}</h2><span class="mono">{{candidate.lat}}°, {{candidate.lon}}° · {{candidate.overall.toFixed(3)}}</span></div><button class="icon-button" :aria-label="t('close')" @click="close">✕</button></div><div v-if="candidate.is_placeholder" class="demo-banner">◈ {{t('placeholder')}}</div>
 <section v-for="task in tasks" :key="task.id" class="drawer-task"><h3>{{task.id}} · {{localized(task,locale)}}</h3><a :href="task.nasa_url" target="_blank" rel="noopener" class="source-link">{{task.nasa_basis}} ↗</a><div class="classification-grid"><div v-for="key in ['similar','different','not_reproducible']" :key="key"><h4 :class="key">{{t(key)}}</h4><p v-for="f in candidate.tasks[task.id]?.features.filter(x=>x.classification===key)" :key="f.feature.id">{{localized(f.feature,locale)}}</p><span v-if="!candidate.tasks[task.id]?.features.some(x=>x.classification===key)" class="muted">—</span></div></div>
 <article v-for="detail in candidate.tasks[task.id]?.features" :key="detail.feature.id" class="feature-detail"><div class="feature-heading"><h4>{{localized(detail.feature,locale)}}</h4><span class="badge" :class="detail.classification">{{detail.score===null?t(detail.classification):detail.score.toFixed(3)}}</span></div><dl class="feature-values"><div><dt>{{t('target')}}</dt><dd>{{format(detail.target_value)}}</dd></div><div><dt>{{t('candidate')}}</dt><dd>{{format(detail.candidate_value)}}</dd></div><div><dt>{{t('methodType')}}</dt><dd>{{detail.feature.type}} / {{detail.feature.compare_mode}}</dd></div><div v-if="detail.feature.unit"><dt>{{t('unit')}}</dt><dd>{{detail.feature.unit}}</dd></div></dl><div v-for="side in ['planet','earth'] as const" :key="side" class="feature-sources"><span class="muted">{{t(side==='planet'?'planetData':'earthData')}}:</span><template v-for="source in detail.feature[side==='planet'?'planet_data':'earth_data']" :key="source.name"><a v-if="source.url" :href="source.url" target="_blank" rel="noopener">{{source.official?'✓':'＋'}} {{source.name}} ↗</a><span v-else>{{source.official?'✓':'＋'}} {{source.name}}</span></template></div><p v-for="note in detail.feature.notes" :key="note" class="small muted">{{note}}</p><p v-for="warning in detail.warnings" :key="warning" class="small warning">{{warning}}</p></article></section>
 <section v-if="seriesFeatures.length"><h3>{{t('series')}}</h3><select :value="selectedFeature" @change="loadSeries(($event.target as HTMLSelectElement).value)"><option v-for="f in seriesFeatures" :key="f.feature.id" :value="f.feature.id">{{localized(f.feature,locale)}}</option></select><p v-if="loading">{{t('loading')}}…</p><p v-if="error" role="alert">{{error}}</p><template v-if="series"><Chart :option="phaseOption" :label="t('phase')"/><Chart :option="ecdfOption" :label="t('ecdf')"/><p class="mono">{{t('wasserstein')}}: {{series.wasserstein.toFixed(4)}}</p></template></section>
 <section><h3>{{t('not_reproducible')}}</h3><p v-for="limit in limits" :key="limit.condition" class="limit-line"><strong>{{limit.condition}}</strong> · {{limit.planet}} / {{limit.reproducible}}<span class="muted"> — {{limit.handling}}</span></p></section>
</div></dialog></template>
